import java.util.*;

public class Main {
    private static final long P = 1000000007L;

    static class FiniteField {
        private long x;

        public FiniteField(long x) {
            if (x < 0 || x >= P) {
                System.err.println("Invalid FiniteField!");
                System.exit(1);
            }
            this.x = x;
        }

        public FiniteField() {
            this.x = 0;
        }

        public long getValue() {
            return x;
        }

        public FiniteField add(FiniteField o) {
            x = (x + o.x) % P;
            return this;
        }

        public FiniteField subtract(FiniteField o) {
            x = (x + P - o.x) % P;
            return this;
        }

        public FiniteField multiply(FiniteField o) {
            x = (x * o.x) % P;
            return this;
        }

        public FiniteField divide(FiniteField o) {
            long exp = P - 2;
            FiniteField base = new FiniteField(o.x);
            FiniteField result = new FiniteField(1);
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    result.multiply(base);
                }
                base.multiply(base);
                exp >>= 1;
            }
            multiply(result);
            return this;
        }

        public FiniteField plus(FiniteField o) {
            return new FiniteField((x + o.x) % P);
        }

        public FiniteField minus(FiniteField o) {
            return new FiniteField((x + P - o.x) % P);
        }

        public FiniteField times(FiniteField o) {
            return new FiniteField((x * o.x) % P);
        }

        public FiniteField over(FiniteField o) {
            long exp = P - 2;
            FiniteField base = new FiniteField(o.x);
            FiniteField result = new FiniteField(1);
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    result.multiply(base);
                }
                base.multiply(base);
                exp >>= 1;
            }
            return new FiniteField((x * result.x) % P);
        }
    }

    // Matrix multiplication: A * B
    private static List<List<FiniteField>> multiplyMatrix(
            List<List<FiniteField>> a, List<List<FiniteField>> b) {
        int n = a.size();
        int m = a.get(0).size();
        if (b.size() != m) {
            System.err.println("Matrix dimensions don't match for multiplication!");
            System.exit(1);
        }
        int l = b.get(0).size();
        List<List<FiniteField>> result = make2DVector(n, l, new FiniteField(0));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < l; j++) {
                FiniteField sum = new FiniteField(0);
                for (int k = 0; k < m; k++) {
                    sum.add(a.get(i).get(k).times(b.get(k).get(j)));
                }
                result.get(i).set(j, sum);
            }
        }
        return result;
    }

    // Matrix * vector
    private static List<FiniteField> multiplyMatrixVector(
            List<List<FiniteField>> matrix, List<FiniteField> v) {
        int n = matrix.size();
        int m = matrix.get(0).size();
        if (v.size() != m) {
            System.err.println("Matrix and vector dimensions don't match for multiplication!");
            System.exit(1);
        }
        List<FiniteField> result = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            FiniteField sum = new FiniteField(0);
            for (int j = 0; j < m; j++) {
                sum.add(matrix.get(i).get(j).times(v.get(j)));
            }
            result.add(sum);
        }
        return result;
    }

    private static <T> List<List<T>> make2DVector(int d1, int d2, T defaultValue) {
        List<List<T>> result = new ArrayList<>(d1);
        for (int i = 0; i < d1; i++) {
            List<T> row = new ArrayList<>(d2);
            for (int j = 0; j < d2; j++) {
                row.add(defaultValue);
            }
            result.add(row);
        }
        return result;
    }

    private static <T> List<List<List<T>>> make3DVector(int d1, int d2, int d3, T defaultValue) {
        List<List<List<T>>> result = new ArrayList<>(d1);
        for (int i = 0; i < d1; i++) {
            result.add(make2DVector(d2, d3, defaultValue));
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        int d = scanner.nextInt();
        scanner.close();

        final boolean DEBUG = false;

        // Build shifts matrix (d x (d+1) x (d+1))
        List<List<List<FiniteField>>> shifts = make3DVector(d, d + 1, d + 1, new FiniteField(0));
        for (int k = 0; k < d; k++) {
            for (int i = 0; i < d; i++) {
                shifts.get(k).get(i).set((i + k) % d, new FiniteField(1));
            }
            shifts.get(k).get(d).set(d, new FiniteField(1));
        }

        // Build units matrix (d x (d+1) x (d+1))
        List<List<List<FiniteField>>> units = make3DVector(d, d + 1, d + 1, new FiniteField(0));
        for (int k = 0; k < d; k++) {
            for (int i = 0; i < d + 1; i++) {
                units.get(k).get(i).set(i, new FiniteField(1));
            }
            for (int i = 0; i < d + 1; i++) {
                units.get(k).get(k).set(i, new FiniteField(1));
            }
        }

        // Identity matrix (d+1 x d+1)
        List<List<FiniteField>> identity = make2DVector(d + 1, d + 1, new FiniteField(0));
        for (int i = 0; i < d + 1; i++) {
            identity.get(i).set(i, new FiniteField(1));
        }

        Map<Long, List<List<FiniteField>>> cache = new HashMap<>();

        // Recursive function using array trick
        @SuppressWarnings("unchecked")
        java.util.function.Function<Long, List<List<FiniteField>>>[] findMatrix = new java.util.function.Function[1];
        findMatrix[0] = (Long p) -> {
            if (cache.containsKey(p)) {
                return cache.get(p);
            }

            if (p <= d) {
                List<List<FiniteField>> matrix = identity;
                for (int k = 0; k < p; k++) {
                    matrix = multiplyMatrix(units.get(k), matrix);
                }
                cache.put(p, matrix);
                return matrix;
            }

            long childP = d;
            while ((p + childP - 1) / childP > d) {
                childP *= d;
            }
            List<List<FiniteField>> child = findMatrix[0].apply(childP);
            List<List<FiniteField>> matrix = child;
            long remainingP = p - childP;
            for (int k = 1; k < d; k++) {
                if (remainingP >= childP) {
                    List<List<FiniteField>> temp = multiplyMatrix(shifts.get(d - k), child);
                    temp = multiplyMatrix(temp, shifts.get(k));
                    matrix = multiplyMatrix(temp, matrix);
                    remainingP -= childP;
                } else if (remainingP > 0) {
                    List<List<FiniteField>> temp = multiplyMatrix(shifts.get(d - k), findMatrix[0].apply(remainingP));
                    temp = multiplyMatrix(temp, shifts.get(k));
                    matrix = multiplyMatrix(temp, matrix);
                    remainingP = 0;
                } else {
                    break;
                }
            }

            cache.put(p, matrix);
            return matrix;
        };

        if (DEBUG) System.err.println("PHASE 1");
        List<List<FiniteField>> matrix = findMatrix[0].apply(n);
        if (DEBUG) System.err.println("PHASE 2");

        List<FiniteField> baseVector = new ArrayList<>(d + 1);
        for (int i = 0; i < d; i++) {
            baseVector.add(new FiniteField(0));
        }
        baseVector.add(new FiniteField(1));

        List<FiniteField> finalVector = multiplyMatrixVector(matrix, baseVector);
        FiniteField ans = new FiniteField(0);
        for (FiniteField x : finalVector) {
            ans.add(x);
        }
        System.out.println(ans.getValue());
    }
}
